// Gelir şelalesinin saf mantığı: basamaklar, göstergeler, ölçek ve yazımlar. Sayılar ve tarihler ABACUS'tandır.
import { math, money } from "@snn/abacus-core";
import { formatMoney, formatMoneyCompact, formatNumber, formatPercent } from "../lib/chart-format";

export type MovementRole = "new" | "expansion" | "reactivation" | "contraction" | "churn";
export interface WaterfallAccount { key: string; name: string; /** Ay ve plan gibi ek bilgi: "Mart 2026 · Pro". */ detail?: string; amount: number }
export interface WaterfallMovement {
  key: string;
  label: string;
  /** Yön: "up" artırır, "down" azaltır. */
  direction: "up" | "down";
  /** Pozitif büyüklük; yön ayrıca verilir. */
  amount: number;
  /** Net elde tutma ve hızlı oran için hareketin türü (isteğe bağlı). */
  role?: MovementRole;
  accounts?: WaterfallAccount[];
  /** Toplam hesap sayısı; verilmezse `accounts.length`. */
  accountCount?: number;
}

export type WaterfallUnit = "amount" | "percent";
export interface WaterfallStep {
  key: string;
  label: string;
  kind: "total" | "up" | "down";
  /** Büyüklük (toplam çubuğunda değerin kendisi). */
  amount: number;
  /** Çubuğun alt ve üst seviyesi (tutar). */
  low: number;
  high: number;
  accountCount: number;
  accounts: WaterfallAccount[];
}

/** Başlangıç, hareketler ve bitiş basamakları; yüzen çubuklar önceki seviyeden başlar. */
export function buildSteps(start: number, movements: WaterfallMovement[], startLabel = "Başlangıç", endLabel = "Bitiş"): WaterfallStep[] {
  let running = start;
  const steps: WaterfallStep[] = [{ key: "start", label: startLabel, kind: "total", amount: start, low: 0, high: start, accountCount: 0, accounts: [] }];
  for (const movement of movements) {
    const from = running, to = running + (movement.direction === "up" ? movement.amount : -movement.amount);
    running = to;
    const accounts = movement.accounts ?? [];
    steps.push({ key: movement.key, label: movement.label, kind: movement.direction, amount: movement.amount, low: Math.min(from, to), high: Math.max(from, to), accountCount: movement.accountCount ?? accounts.length, accounts });
  }
  steps.push({ key: "end", label: endLabel, kind: "total", amount: running, low: 0, high: running, accountCount: 0, accounts: [] });
  return steps;
}

export interface WaterfallIndicators {
  /** Net elde tutma: (başlangıç + genişleme − daralma − kayıp) / başlangıç, yüzde. Başlangıç sıfırsa null. */
  netRetention: number | null;
  /** Hızlı oran: kazanılan / kaybedilen. Kayıp sıfırsa null. */
  quickRatio: number | null;
  /** Müşteri kaybı: kayıp / başlangıç, yüzde. */
  churn: number | null;
}

export function indicators(start: number, movements: WaterfallMovement[]): WaterfallIndicators {
  const sum = (roles: MovementRole[]) => movements.filter(movement => movement.role && roles.includes(movement.role)).reduce((total, movement) => total + movement.amount, 0);
  const gained = sum(["new", "expansion", "reactivation"]), lost = sum(["contraction", "churn"]);
  return {
    netRetention: start > 0 ? ((start + sum(["expansion"]) - lost) / start) * 100 : null,
    quickRatio: lost > 0 ? gained / lost : null,
    churn: start > 0 ? (sum(["churn"]) / start) * 100 : null,
  };
}

/** Eksen üst sınırı: en büyük seviyeyi aşan 1-2-2,5-5 basamaklı değer; çubuklar "güzel" aralıkta durur. */
export function niceTop(max: number): number {
  if (!(max > 0)) return 1;
  const magnitude = 10 ** Math.floor(Math.log10(max));
  for (const factor of [1, 2, 2.5, 5, 10]) if (factor * magnitude >= max) return factor * magnitude;
  return 10 * magnitude;
}

/** Değeri birime göre yazar: tutar "₺1.250.000" (tam) ya da "₺1,25Mn" (kısa); yüzde birimde başlangıca göre "%112,5". */
export function stepValueText(unit: WaterfallUnit, value: number, base: number, short = false): string {
  if (unit === "percent") return formatPercent(base > 0 ? (value / base) * 100 : 0, 1);
  return short ? formatMoneyCompact(Math.round(value)) : formatMoney(Math.round(value), 0);
}

/** İşaretli hareket yazımı: "+₺120B", "-₺40B" (eksi ABACUS'tan gelir); yüzde birimde "+%12,5". */
export function signedText(unit: WaterfallUnit, step: Pick<WaterfallStep, "kind" | "amount">, base: number, short = true): string {
  if (step.kind === "total") return stepValueText(unit, step.amount, base, short);
  if (unit === "percent") return money.percent((base > 0 ? step.amount / base : 0) * 100 * (step.kind === "down" ? -1 : 1), 1, { sign: "always" });
  return step.kind === "up" ? `+${stepValueText(unit, step.amount, base, short)}` : (short ? formatMoneyCompact(-Math.round(step.amount)) : formatMoney(-Math.round(step.amount), 0));
}

/** Dönem boyu değişim: "+₺180.000 (+%12,3)". */
export function periodChangeText(start: number, end: number): string {
  const diff = Math.round(end - start);
  const change = math.percentChange(end, start);
  const amount = diff >= 0 ? `+${formatMoney(diff, 0)}` : formatMoney(diff, 0);
  return change === null ? amount : `${amount} (${money.percent(change, 1, { sign: "always" })})`;
}

export const retentionText = (percent: number) => formatPercent(percent, 1);
export const ratioText = (ratio: number) => money.fmtDecimalGrouped(ratio, 2);
export const countText = (count: number) => formatNumber(count, 0);

/** Ekran okuyucu: "Yeni: +₺120.000, 14 hesap". */
export function stepAnnouncement(unit: WaterfallUnit, step: WaterfallStep, base: number): string {
  return `${step.label}: ${signedText(unit, step, base, false)}${step.kind === "total" ? "" : `, ${countText(step.accountCount)} hesap`}`;
}

.root { container-type: inline-size; display: grid; min-width: 0; gap: var(--space-5); padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); }
.header { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: var(--space-3); }
.titles { min-width: 0; }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-xl); font-weight: 500; letter-spacing: var(--tracking-display); }
.subtitle { margin: 2px 0 0; color: var(--text-secondary); font-size: var(--text-sm); }
.tools { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.summary { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: var(--space-5); }
.endBlock { display: grid; gap: var(--space-1); }
.statValue { font-family: var(--font-display); font-size: var(--text-4xl); letter-spacing: var(--tracking-display); line-height: var(--leading-display); font-variant-numeric: tabular-nums; }
.asOf { color: var(--text-secondary); font-size: var(--text-sm); }
.change { color: var(--success); font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.marks { display: flex; flex-wrap: wrap; gap: var(--space-6); margin: 0; }
.marks div { display: grid; gap: 2px; }
.marks dt { color: var(--text-secondary); font-size: var(--text-xs); }
.marks dd { margin: 0; font-family: var(--font-display); font-size: var(--text-xl); font-variant-numeric: tabular-nums; }
.body { display: grid; grid-template-columns: minmax(0, 1fr) 17rem; gap: var(--space-5); align-items: start; }
.chart { min-width: 0; }
.svg { display: block; overflow: visible; }
.grid { stroke: var(--border); stroke-width: 1; shape-rendering: crispEdges; }
.axisText { fill: var(--text-muted); font-size: 11px; }
.step { outline: none; cursor: pointer; transition: opacity var(--duration-fast) var(--ease-standard); }
.step[data-dim] { opacity: .45; }
.hit { fill: transparent; }
.bar { transition: opacity var(--duration-fast) var(--ease-standard); }
.step[data-selected] .bar { stroke: var(--foreground); stroke-width: 2; }
.step:focus-visible .bar { stroke: var(--foreground); stroke-width: 2; }
.valueText { fill: var(--foreground); font-size: 12px; font-weight: 500; font-variant-numeric: tabular-nums; }
.labelText { fill: var(--text-secondary); font-size: 11px; }
.panel { min-width: 0; padding: var(--space-4); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-muted); }
.panelTitle { margin: 0; font-size: var(--text-sm); font-weight: 500; }
.panelSum { margin: 2px 0 var(--space-3); color: var(--text-secondary); font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.hint { margin: 0; color: var(--text-muted); font-size: var(--text-sm); }
.accounts { display: grid; gap: var(--space-1); margin: 0; padding: 0; list-style: none; }
.account { position: relative; display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); min-height: 2.5rem; padding: 0 var(--space-2); font-size: var(--text-sm); }
.accountFill { position: absolute; inset: 0 auto 0 0; border-radius: var(--radius-control); background: var(--accent-subtle); }
.accountName { position: relative; display: grid; min-width: 0; }
.accountName small { color: var(--text-muted); font-size: var(--text-xs); }
.accountAmount { position: relative; font-variant-numeric: tabular-nums; white-space: nowrap; }
.error { display: flex; align-items: center; justify-content: center; gap: var(--space-3); padding: var(--space-8) 0; color: var(--danger); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
@container (max-width: 800px) { .body { grid-template-columns: minmax(0, 1fr); } }
@container (max-width: 560px) { .root { padding: var(--space-4); } .marks { gap: var(--space-3); flex-wrap: nowrap; } .marks dd { font-size: var(--text-base); } .statValue { font-size: var(--text-3xl); } }
.root[data-reduced] .step, .root[data-reduced] .bar { transition: none; }
@media (prefers-reduced-motion: reduce) { .step, .bar { transition: none; } }

"use client";

import { useMemo, useState, type KeyboardEvent } from "react";
import { motion } from "motion/react";
import { AnimatedCounter } from "../animated-counter/animated-counter";
import { Button } from "../button/button";
import { clamp, useElementWidth, useReducedMotionSafe } from "../lib/viz-utils";
import { formatMoneyCompact, formatRatio } from "../lib/chart-format";
import SegmentedControl from "../segmented-control/segmented-control";
import { Skeleton } from "../skeleton/skeleton";
import { buildSteps, countText, indicators, niceTop, periodChangeText, ratioText, retentionText, signedText, stepAnnouncement, stepValueText, type WaterfallAccount, type WaterfallMovement, type WaterfallUnit } from "./mrr-waterfall-format";
import styles from "./mrr-waterfall.module.css";

export type { WaterfallAccount, WaterfallMovement, WaterfallUnit };
export interface WaterfallPeriod { value: string; label: string }

/** Düzenli gelirin dönem başından sonuna nasıl değiştiğini köprü grafiğiyle (başlangıç, artışlar, azalışlar, bitiş) anlatmak için kullanın; aylar boyunca seyir için gelir gezgini daha doğrudur. */
export interface MrrWaterfallProps {
  /** Dönem başındaki toplam gelir (TRY). */
  start: number;
  movements: WaterfallMovement[];
  title?: string;
  /** Alt satır: kapsam ve tarih aralığı, örneğin "Tüm planlar · 1 Temmuz – 30 Eylül 2026". */
  subtitle?: string;
  /** Büyük bitiş değerinin altındaki metin, örneğin "30 Eylül itibarıyla". */
  asOf?: string;
  periods?: WaterfallPeriod[];
  period?: string;
  onPeriodChange?: (value: string) => void;
  status?: "ready" | "loading" | "error";
  onRetry?: () => void;
  /** Panelde gösterilen en çok hesap sayısı; kalanlar "Diğer hesaplar" satırında toplanır. */
  maxAccounts?: number;
}

const HEIGHT = 280, TOP = 22, BOTTOM = 34;
const toneOf = (kind: "total" | "up" | "down") => kind === "total" ? "var(--accent)" : kind === "up" ? "var(--series-3)" : "var(--series-2)";

export function MrrWaterfall({ start, movements, title = "Gelir köprüsü", subtitle, asOf, periods, period, onPeriodChange, status = "ready", onRetry, maxAccounts = 5 }: MrrWaterfallProps) {
  const reduced = useReducedMotionSafe();
  const [box, width] = useElementWidth<HTMLDivElement>();
  const [unit, setUnit] = useState<WaterfallUnit>("amount");
  const [selected, setSelected] = useState<string | null>(null);
  const [hover, setHover] = useState<string | null>(null);
  const [announce, setAnnounce] = useState("");
  const steps = useMemo(() => buildSteps(start, movements), [start, movements]);
  const end = steps[steps.length - 1]?.amount ?? 0;
  const marks = useMemo(() => indicators(start, movements), [start, movements]);
  const chosen = steps.find(step => step.key === selected) ?? null;

  const plotWidth = Math.max(width, 1), column = plotWidth / steps.length, barWidth = Math.min(56, column * .6);
  const top = unit === "percent" ? niceTop(Math.max(...steps.map(step => step.high)) / (start || 1)) * (start || 1) : niceTop(Math.max(...steps.map(step => step.high), 1));
  const plotHeight = HEIGHT - TOP - BOTTOM;
  const yOf = (value: number) => TOP + (1 - value / top) * plotHeight;
  const ticks = [0, .25, .5, .75, 1].map(share => top * share);

  const pick = (key: string | null) => {
    setSelected(key);
    const step = steps.find(item => item.key === key);
    if (step) setAnnounce(stepAnnouncement(unit, step, start));
  };
  const onKeyDown = (event: KeyboardEvent<SVGGElement>) => {
    const at = steps.findIndex(step => step.key === selected);
    const move = event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 0;
    if (move) { event.preventDefault(); pick(steps[(clamp(at, -1, steps.length) + move + steps.length) % steps.length]?.key ?? null); }
    else if (event.key === "Home") { event.preventDefault(); pick(steps[0]?.key ?? null); }
    else if (event.key === "End") { event.preventDefault(); pick(steps[steps.length - 1]?.key ?? null); }
    else if (event.key === "Escape") pick(null);
  };

  if (status === "loading") return <section className={styles.root} aria-busy="true"><Skeleton label="Gelir köprüsü yükleniyor" lines={6} /></section>;
  if (status === "error") return <section className={styles.root}><div className={styles.error} role="alert"><span>Yüklenemedi.</span>{onRetry && <Button size="sm" variant="secondary" onClick={onRetry}>Yeniden dene</Button>}</div></section>;

  const list = chosen?.accounts ?? [];
  const shown = list.slice(0, maxAccounts);
  const rest = list.slice(maxAccounts);
  const restSum = rest.reduce((sum, account) => sum + account.amount, 0);
  const restCount = Math.max((chosen?.accountCount ?? 0) - shown.length, 0);
  const peak = Math.max(...list.map(account => account.amount), restSum, 1);
  const showAmount = (value: number) => stepValueText("amount", value, start);

  return <section className={styles.root} data-reduced={reduced || undefined} aria-label={title}>
    <header className={styles.header}>
      <div className={styles.titles}><h3 className={styles.title}>{title}</h3>{subtitle && <p className={styles.subtitle}>{subtitle}</p>}</div>
      <div className={styles.tools}>
        {periods && period !== undefined && onPeriodChange && <SegmentedControl label="Dönem" value={period} onValueChange={onPeriodChange} options={periods} />}
        <SegmentedControl label="Birim" value={unit} onValueChange={value => setUnit(value as WaterfallUnit)} options={[{ value: "amount", label: "Tutar" }, { value: "percent", label: "Başlangıca göre %" }]} />
      </div>
    </header>

    <div className={styles.summary}>
      <div className={styles.endBlock}>
        <span className={styles.statValue} aria-label={showAmount(end)}><AnimatedCounter value={Math.round(end)} prefix="₺" /></span>
        {asOf && <span className={styles.asOf}>{asOf}</span>}
        <span className={styles.change}>{periodChangeText(start, end)}</span>
      </div>
      <dl className={styles.marks}>
        <div><dt>Net elde tutma</dt><dd>{marks.netRetention === null ? "—" : retentionText(marks.netRetention)}</dd></div>
        <div><dt>Hızlı oran</dt><dd>{marks.quickRatio === null ? "—" : ratioText(marks.quickRatio)}</dd></div>
        <div><dt>Müşteri kaybı</dt><dd>{marks.churn === null ? "—" : retentionText(marks.churn)}</dd></div>
      </dl>
    </div>

    <div className={styles.body}>
      <div ref={box} className={styles.chart}>
        <svg className={styles.svg} width={plotWidth} height={HEIGHT} role="img" aria-label={`${title}: ${steps.map(step => `${step.label} ${signedText(unit, step, start, false)}`).join(", ")}`}>
          {ticks.map(tick => <g key={tick}><line className={styles.grid} x1={0} x2={plotWidth} y1={yOf(tick)} y2={yOf(tick)} /><text className={styles.axisText} x={0} y={yOf(tick) - 4}>{unit === "percent" ? formatRatio(tick / (start || 1), 0) : formatMoneyCompact(tick)}</text></g>)}
          <g role="radiogroup" aria-label="Basamaklar" onKeyDown={onKeyDown}>
            {steps.map((step, at) => {
              const x = column * at + (column - barWidth) / 2;
              const y = yOf(step.high), h = Math.max(2, yOf(step.low) - yOf(step.high));
              const isSelected = selected === step.key;
              return <g key={step.key} role="radio" aria-checked={isSelected} aria-label={stepAnnouncement(unit, step, start)} tabIndex={isSelected || (selected === null && at === 0) ? 0 : -1} className={styles.step}
                data-selected={isSelected || undefined} data-dim={(hover && hover !== step.key && !isSelected) || undefined}
                onClick={() => pick(step.key)} onPointerEnter={event => { if (event.pointerType === "mouse") setHover(step.key); }} onPointerLeave={() => setHover(null)} onFocus={() => { if (selected !== step.key) setSelected(step.key); }}>
                <rect className={styles.hit} x={column * at} y={0} width={column} height={HEIGHT} />
                <motion.rect className={styles.bar} rx={4} x={x} width={barWidth} style={{ fill: toneOf(step.kind) }} initial={false} animate={{ y, height: h }} transition={reduced ? { duration: 0 } : { type: "spring", visualDuration: .4, bounce: .05 }} />
                <text className={styles.valueText} x={column * at + column / 2} y={Math.max(12, y - 6)} textAnchor="middle">{signedText(unit, step, start)}</text>
                <text className={styles.labelText} x={column * at + column / 2} y={HEIGHT - 12} textAnchor="middle">{step.label}</text>
              </g>;
            })}
          </g>
        </svg>
      </div>

      <aside className={styles.panel} aria-label="Hesaplar">
        {!chosen && <p className={styles.hint}>Bir çubuğu seçin ya da ok tuşlarını kullanın.</p>}
        {chosen && <>
          <h4 className={styles.panelTitle}>{chosen.label}</h4>
          <p className={styles.panelSum}>{signedText("amount", chosen, start, false)}{chosen.kind !== "total" && <span> · {countText(chosen.accountCount)} hesap</span>}</p>
          {chosen.kind === "total" || !chosen.accountCount ? <p className={styles.hint}>{chosen.kind === "total" ? "Bu çubuk için hesap listesi yok." : "Hesap yok."}</p> : <ul className={styles.accounts}>
            {shown.map(account => <motion.li key={account.key} layout={!reduced} className={styles.account} transition={{ duration: .25 }}>
              <span className={styles.accountFill} style={{ width: `${(account.amount / peak) * 100}%` }} aria-hidden="true" />
              <span className={styles.accountName}>{account.name}{account.detail && <small>{account.detail}</small>}</span>
              <span className={styles.accountAmount}>{showAmount(account.amount)}</span>
            </motion.li>)}
            {restCount > 0 && <li className={styles.account}><span className={styles.accountName}>Diğer hesaplar ({countText(restCount)} hesap)</span><span className={styles.accountAmount}>{showAmount(restSum || Math.max(chosen.amount - shown.reduce((sum, account) => sum + account.amount, 0), 0))}</span></li>}
          </ul>}
        </>}
      </aside>
    </div>

    <div className={styles.srOnly}><table>
      <caption>{title}</caption>
      <thead><tr><th scope="col">Basamak</th><th scope="col">Tutar</th><th scope="col">Başlangıca göre pay</th><th scope="col">Hesap sayısı</th></tr></thead>
      <tbody>{steps.map(step => <tr key={step.key}><th scope="row">{step.label}</th><td>{signedText("amount", step, start, false)}</td><td>{stepValueText("percent", step.amount, start)}</td><td>{step.kind === "total" ? "—" : countText(step.accountCount)}</td></tr>)}</tbody>
    </table></div>
    <p className={styles.srOnly} aria-live="polite" aria-atomic="true">{announce}</p>
  </section>;
}

export default MrrWaterfall;
